def fichiers_vers_fichier_rendu(apps, schema_editor):
    # Un rendu existant (un fichier, individuel) devient une ligne de FichierRendu.
    Soumission = apps.get_model('core', 'Soumission')
    FichierRendu = apps.get_model('core', 'FichierRendu')
    racine = Path(settings.UPLOAD_ROOT)
    for soumission in Soumission.objects.exclude(chemin_fichier__isnull=True).exclude(chemin_fichier=''):
        try:
            taille = (racine / soumission.chemin_fichier).stat().st_size
        except OSError:
            taille = 0
        FichierRendu.objects.create(
            soumission=soumission,
            chemin=soumission.chemin_fichier,
            nom_original=soumission.nom_original or 'fichier',
            taille=taille,
            date_depot=soumission.date_soumission,
        )
        soumission.type = 'fichier'
        soumission.deposee_par_id = soumission.etudiant_id
        soumission.save(update_fields=['type', 'deposee_par'])


def fichier_rendu_vers_fichiers(apps, schema_editor):
    Soumission = apps.get_model('core', 'Soumission')
    for soumission in Soumission.objects.filter(etudiant__isnull=False):
        fichier = soumission.fichiers.order_by('id').first()
        if fichier is not None:
            soumission.chemin_fichier = fichier.chemin
            soumission.nom_original = fichier.nom_original
            soumission.save(update_fields=['chemin_fichier', 'nom_original'])


